def translated_block(document, index, kind, value):
    """Pair one source block, preserving shared numerical table cells."""
    if kind == 'equation':
        return value, value
    english = EN.get(document, {}).get(index, value[1] if kind == 'heading' else value)
    if index not in ZH.get(document, {}):
        raise ValueError(f'Missing Chinese block: {document}:{index} ({kind})')
    chinese = ZH[document][index]
    if kind == 'heading':
        return (value[0], english), (value[0], chinese)
    if kind == 'table':
        if isinstance(chinese[0], str):
            table = deepcopy(english)
            if len(chinese) != len(table[0]):
                raise ValueError(f'Chinese column mismatch: {document}:{index}')
            table[0] = chinese
            chinese = table
        if len(english) != len(chinese) or any(len(a) != len(b) for a,b in zip(english,chinese)):
            raise ValueError(f'Chinese table mismatch: {document}:{index}')
        for enrow,zhrow in zip(english[1:],chinese[1:]):
            for en,zh in zip(enrow,zhrow):
                if re.fullmatch(r'[\d.]+(?:\s*(?:pJ|nJ|%))?',en) and en != zh:
                    raise ValueError(f'Numerical table cell changed: {document}:{index}: {en}')
    return english, chinese
